_LINK_CACHE = {}


def chain_link(kind, angle):
  key = (kind, round(angle))
  if key not in _LINK_CACHE:
    surf = pygame.Surface((40, 24), pygame.SRCALPHA)
    if kind == 0:
      pygame.draw.ellipse(surf, (86, 92, 103), (2, 4, 36, 16), 6)
      pygame.draw.ellipse(surf, (194, 200, 206), (7, 7, 26, 10), 2)
      pygame.draw.arc(surf, (255, 255, 255, 100), (8, 6, 20, 8), math.pi, 2 * math.pi, 2)
    else:
      pygame.draw.ellipse(surf, (92, 96, 109), (8, 2, 24, 20), 6)
      pygame.draw.ellipse(surf, (197, 201, 208), (12, 6, 16, 12), 2)
    _LINK_CACHE[key] = pygame.transform.rotate(surf, -angle)
  return _LINK_CACHE[key]


def draw_chain(p1, p2):
  dx, dy = p2[0] - p1[0], p2[1] - p1[1]
  dist = math.hypot(dx, dy)
  if dist == 0:
    return
  angle = math.degrees(math.atan2(dy, dx))
  step = 20
  for i in range(int(dist // step) + 1):
    t = i * step / dist
    s = chain_link(i % 2, angle)
    SCREEN.blit(s, (p1[0] + dx * t - s.get_width() // 2, p1[1] + dy * t - s.get_height() // 2))


def draw_padlock(cx, cy):
  pygame.draw.arc(SCREEN, (108, 112, 120), (cx - 16, cy - 31, 32, 34), 0, math.pi, 6)
  pygame.draw.arc(SCREEN, (208, 212, 216), (cx - 13, cy - 28, 26, 28), 0, math.pi, 2)
  body = pygame.Rect(cx - 22, cy - 3, 44, 34)
  pygame.draw.rect(SCREEN, (214, 164, 54), body, border_radius=8)
  pygame.draw.rect(SCREEN, (120, 84, 21), body, 3, border_radius=8)
  pygame.draw.rect(SCREEN, (236, 197, 93), (body.x + 4, body.y + 4, body.w - 8, 8), border_radius=4)
  pygame.draw.circle(SCREEN, (71, 51, 15), (cx, cy + 10), 5)
  pygame.draw.rect(SCREEN, (71, 51, 15), (cx - 2, cy + 11, 4, 10), border_radius=2)


def draw_locked_overlay(rect):
  veil = pygame.Surface(rect.size, pygame.SRCALPHA)
  pygame.draw.rect(veil, (16, 18, 22, 55), veil.get_rect(), border_radius=14)
  SCREEN.blit(veil, rect.topleft)
  prev_clip = SCREEN.get_clip()
  SCREEN.set_clip(rect.inflate(-6, -8))
  draw_chain((rect.x + 8, rect.y + 12), (rect.right - 8, rect.bottom - 12))
  draw_chain((rect.x + 8, rect.bottom - 12), (rect.right - 8, rect.y + 12))
  SCREEN.set_clip(prev_clip)


