def shop_cards(tab, page=0):
  keys = list(shop_table(tab))[page * 6:(page + 1) * 6]
  cards = []
  for i, key in enumerate(keys):
    col, row = i % 3, i // 3
    cards.append((pygame.Rect(35 + col * 215, 160 + row * 200, 200, 190), key))
