HOME_TOOLS = {"shop":"Botiga", "settings":"Configuració", "saves":"Partides", "achievements":"Assoliments"}


def home_rects():
  return {
      "morris": pygame.Rect(35, 155, 190, 170),
      "c4": pygame.Rect(255, 155, 190, 170),
      "chess": pygame.Rect(475, 155, 190, 170),
      "go": pygame.Rect(35, 345, 190, 170),
      "shogi": pygame.Rect(255, 345, 190, 170),
      "dino": pygame.Rect(475, 345, 190, 170),
      "shop": pygame.Rect(72, 540, 120, 78),
      "settings": pygame.Rect(210, 540, 120, 78),
      "saves": pygame.Rect(348, 540, 120, 78),
      "achievements": pygame.Rect(486, 540, 120, 78),
  }


def main_menu_pick(opts, events):
  rects = home_rects()
  for ev in events:
    if ev.type == pygame.KEYDOWN:
      for i, ks in enumerate(NUM_KEYS[:len(opts)]):
        if ev.key in ks and opts[i][3]:
          return opts[i][0]
    elif ev.type == pygame.MOUSEBUTTONDOWN and ev.button == 1:
      for key, _, _, enabled, *rest in opts:
        if enabled and rects[key].collidepoint(ev.pos):
          return key
  return None


def home_label(txt, center, font, color):
  t = font.render(txt, True, color)
  SCREEN.blit(t, t.get_rect(center=center))


def draw_dino_icon(area):
  pygame.draw.rect(SCREEN, (243, 220, 171), area, border_radius=12)
  pygame.draw.line(SCREEN, (164, 131, 78), (area.x + 8, area.bottom - 16), (area.right - 8, area.bottom - 16), 3)
  body = pygame.Rect(area.x + 45, area.y + 46, 46, 32)
  pygame.draw.rect(SCREEN, (76, 78, 79), body, border_radius=4)
  pygame.draw.rect(SCREEN, (76, 78, 79), (body.x + 32, body.y - 14, 18, 18), border_radius=4)
  pygame.draw.circle(SCREEN, (245, 245, 245), (body.x + 42, body.y - 5), 2)
  for lx in (body.x + 8, body.x + 26):
    pygame.draw.line(SCREEN, (76, 78, 79), (lx, body.bottom), (lx - 3, body.bottom + 18), 4)
  pygame.draw.line(SCREEN, (76, 78, 79), (body.right - 5, body.y + 9), (body.right + 14, body.y + 15), 4)
  pygame.draw.line(SCREEN, (76, 78, 79), (body.x + 3, body.y + 6), (body.x - 16, body.y - 5), 4)
  for x in (area.right - 66, area.right - 46):
    pygame.draw.line(SCREEN, (69, 123, 76), (x, area.bottom - 16), (x, area.bottom - 44), 4)
    pygame.draw.line(SCREEN, (69, 123, 76), (x - 7, area.bottom - 33), (x + 7, area.bottom - 33), 4)


def home_cover(key, area):
  pygame.draw.rect(SCREEN, (242,223,186), area, border_radius=12)
  if key == "shogi":
    draw_menu_icon(key, area.inflate(-6, -6))
    return
  if key in MENU_IMAGE_DATA:
    ck = (key, area.size)
    if ck not in _MENU_IMAGE_CACHE:
      image = None
      names = {"c4":("c4.png",), "chess":("chess.jpg","chess.png"), "go":("go.jpg","go.png"), "shogi":("shogi.jpg","shogi.png"), "dino":("dino.png","dino.jpg")}
      for root in (os.path.dirname(os.path.abspath(__file__)), os.getcwd()):
        for name in names.get(key, ()):
          try:
            image = pygame.image.load(os.path.join(root,"assets","menu",name)).convert_alpha()
            break
          except (OSError, pygame.error):
            pass
        if image is not None: break
      if image is None:
        try:
          raw = zlib.decompress(base64.b64decode(MENU_IMAGE_DATA[key]))
          image = pygame.image.fromstring(raw, MENU_IMAGE_SIZE, "RGBA").convert_alpha()
        except Exception as exc:
          print("Portada", key, exc)
      if image is not None:
        iw,ih=image.get_size(); aw,ah=area.size
        if key == "c4":
          f = min((aw - 8) / iw, (ah - 8) / ih)
        elif key == "dino":
          f = min((aw - 4) / iw, (ah - 4) / ih) * 1.45
        else:
          f = max(aw / iw, ah / ih)
        w,h=max(1,round(iw*f)),max(1,round(ih*f))
        tile=pygame.Surface(area.size,pygame.SRCALPHA)
        tile.blit(pygame.transform.smoothscale(image,(w,h)),((aw-w)//2,(ah-h)//2))
        mask=pygame.Surface(area.size,pygame.SRCALPHA)
        pygame.draw.rect(mask,(255,255,255,255),mask.get_rect(),border_radius=12)
        tile.blit(mask,(0,0),special_flags=pygame.BLEND_RGBA_MULT)
        _MENU_IMAGE_CACHE[ck]=tile
      else:
        _MENU_IMAGE_CACHE[ck]=None
    if _MENU_IMAGE_CACHE[ck] is not None:
      SCREEN.blit(_MENU_IMAGE_CACHE[ck],area.topleft)
      return
  if key=="dino": draw_dino_icon(area)
  else: draw_menu_icon(key,area.inflate(-10,-10))


def home_tool_icon(key, center, color, size=54):
  icon=pygame.Surface((100,100),pygame.SRCALPHA)
  x,y=50,50; c=color
  if key=='shop':
    pygame.draw.arc(icon,c,(32,8,36,42),0,math.pi,7)
    pygame.draw.polygon(icon,c,[(25,34),(75,34),(87,87),(13,87)])
    pygame.draw.circle(icon,(247,232,200),(50,60),12,4)
  elif key=='settings':
    for i in range(8):
      a=i*math.pi/4
      pts=[(x+r*math.cos(a+d),y+r*math.sin(a+d)) for r,d in ((30,-.24),(44,-.17),(44,.17),(30,.24))]
      pygame.draw.polygon(icon,c,pts)
    pygame.draw.circle(icon,c,(50,50),34); pygame.draw.circle(icon,(0,0,0,0),(50,50),14)
  elif key=='saves':
    pygame.draw.polygon(icon,c,[(15,12),(72,12),(86,26),(86,87),(15,87)])
    pygame.draw.rect(icon,(247,232,200),(29,15,42,27),border_radius=3)
    pygame.draw.rect(icon,(247,232,200),(27,54,47,30),border_radius=4)
    pygame.draw.rect(icon,c,(59,18,8,18),border_radius=2)
  else:
    pygame.draw.arc(icon,c,(7,16,55,51),math.pi/2,3*math.pi/2,6)
    pygame.draw.arc(icon,c,(38,16,55,51),-math.pi/2,math.pi/2,6)
    pygame.draw.polygon(icon,c,[(24,12),(76,12),(72,43),(62,59),(50,64),(38,59),(28,43)])
    pygame.draw.rect(icon,c,(45,59,10,21)); pygame.draw.rect(icon,c,(29,78,42,9),border_radius=4)
  icon=pygame.transform.smoothscale(icon,(size,size))
  SCREEN.blit(icon,icon.get_rect(center=center))


def draw_home_menu(app, opts, mouse):
  draw_background("menu")
  pygame.draw.line(SCREEN, (134, 160, 149), (38, 125), (245, 125), 1)
  pygame.draw.line(SCREEN, (134, 160, 149), (455, 125), (662, 125), 1)
  ink=(60,46,34); muted=(104,87,68); gold=(183,126,41)
  home_label('RATLLA', (350, 42), BIG_FONT, ink)
  home_label('Jocs de taula i arcade', (350, 81), TITLE_FONT, muted)
  coin = pygame.Rect(265, 102, 170, 34)
  pygame.draw.rect(SCREEN, (253,239,204), coin, border_radius=17)
  pygame.draw.circle(SCREEN, gold, (coin.x + 18, coin.centery), 10)
  pygame.draw.circle(SCREEN, (253,223,123), (coin.x + 18, coin.centery), 6, 2)
  home_label(f"{SAVE['points']} punts", (coin.centerx + 10, coin.centery), FONT, ink)

  rects = home_rects()
  for key in ('morris','c4','chess','go','shogi','dino'):
    r = rects[key]
    hover = r.collidepoint(mouse)
    shadow = r.move(0, 5)
    pygame.draw.rect(SCREEN, (154, 171, 181), shadow, border_radius=18)
    pygame.draw.rect(SCREEN, (252, 238, 209) if hover else (246, 232, 204), r, border_radius=18)
    pygame.draw.rect(SCREEN, gold if hover else (157, 127, 88), r, 3 if hover else 2, border_radius=18)
    area = pygame.Rect(r.x + 11, r.y + 11, r.w - 22, 104)
    home_cover(key, area)
    home_label(HOME_TITLES[key], (r.centerx, r.bottom - 40), FONT, ink)
    home_label(HOME_DESCRIPTIONS[key], (r.centerx, r.bottom - 18), SMALL, muted)

  for key, label in HOME_TOOLS.items():
    r = rects[key]; hover = r.collidepoint(mouse)
    pygame.draw.rect(SCREEN, (246,232,204) if hover else (241,226,195), r, border_radius=16)
    pygame.draw.rect(SCREEN, gold if hover else (157,127,88), r, 2, border_radius=16)
    col = gold if key in ('shop','achievements') else (89, 110, 117)
    home_tool_icon(key, (r.centerx, r.y + 26), col, 34)
    home_label(label, (r.centerx, r.y + 54), SMALL, ink)
    if key == 'saves':
      n = sum(x is not None for x in SAVE['slots'])
      home_label(f'{n}/10', (r.centerx, r.y + 70), SMALL, muted)
    elif key == 'achievements':
      refresh_achievements()
      home_label(f"{len(SAVE['achievements'])}/{len(ACH)}", (r.centerx, r.y + 70), SMALL, muted)
    else:
      home_label(' ', (r.centerx, r.y + 70), SMALL, muted)

  home_label('Tria un joc per començar', (350, 655), FONT, muted)
  home_label('Local · Contra bots · Un jugador', (350, 680), SMALL, muted)


