def draw_dino(app):
  g=app.game; draw_background('dino'); stage=dino_landscape(g)
  for p in g.pickups: dino_draw_pickup(p,g)
  for h in g.hazards: dino_draw_hazard(h,g)
  dino_draw_player(g)
  # HUD i controls de contrast alt, independents del fons equipat.
  pygame.draw.rect(SCREEN,(28,45,43),(14,14,672,85),border_radius=16)
  dino_text('DINO RUN',(113,37),TITLE_FONT,(248,221,137)); dino_text(stage,(113,68))
  for x,label,value in ((283,'PUNTS',str(g.score)),(397,'TEMPS',f'{g.seconds:.1f}s'),(500,'MONEDES',str(g.coins)),(612,'RÈCORD',str(max(g.score,SAVE.get('dino_best',0))))):
    dino_text(label,(x,35),SMALL,(171,199,186)); dino_text(value,(x,65),TITLE_FONT)
  pygame.draw.rect(SCREEN,(32,48,43),(18,112,664,39),border_radius=10)
  dino_text(f"Nivell {1+int(g.seconds//15)} · velocitat {g.speed/5.8:.1f}x",(157,131))
  dino_text(('Escut actiu' if g.shield else 'Sense escut')+(' · Imant '+str((g.magnet+59)//60)+'s' if g.magnet else ''),(511,131))
  if g.warning:
    pygame.draw.rect(SCREEN,(101,62,31),(18,171,275,46),border_radius=12); dino_text('! Obstacles per l’esquerra',(155,194),FONT,(255,230,165))
  if g.notice_timer: dino_text(g.notice,(350,175),FONT,(30,74,58) if stage!='Nit estrellada' else (249,240,204))
  pygame.draw.rect(SCREEN,(28,45,43),(0,625,WIDTH,125))
  dino_text('ESPAI / ↑ salt doble  ·  ↓ ajupir-se  ·  P pausa',(350,645),SMALL)
  dino_text(f'+{g.reward()} punts de botiga en acabar · esquiva obstacles i recull monedes',(350,667),SMALL,(237,203,117))
  labels={'menu':'Menú','restart':'Reinicia','save':'Desa','pause':'Continua' if g.paused else 'Pausa','duck':'↓ Ajupir','jump':'↑ Saltar'}
  for k,r in dino_control_rects():
    on=r.collidepoint(mouse_pos()); col=(231,196,111) if k in ('jump','duck') else (61,87,76)
    if on: col=dino_mix(col,(255,255,255),.19)
    pygame.draw.rect(SCREEN,col,r,border_radius=10); dino_text(labels[k],r.center,SMALL,(31,47,41) if k in ('jump','duck') else (241,244,230))
  if not g.winner and (g.paused or not g.started):
    pygame.draw.rect(SCREEN,(28,45,43),(87,267,526,133),border_radius=20); pygame.draw.rect(SCREEN,(235,196,111),(87,267,526,133),2,border_radius=20)
    dino_text('PARTIDA EN PAUSA' if g.paused else 'SAVANNA ADVENTURE',(350,305),TITLE_FONT,(248,221,137))
    dino_text('Prem P o toca Continua' if g.paused else 'Prem ESPAI o toca Saltar per començar',(350,348),FONT)
    dino_text('El temps només compta mentre jugues.',(350,378),SMALL,(175,201,185))

def process_dino(app,events):
  g=app.game
  for ev in events:
    if ev.type==getattr(pygame,'WINDOWFOCUSLOST',-999):
      if g.started and not g.winner: g.paused=True; g.accum=0.; g.duck=False; g.duck_timer=0
    elif ev.type==pygame.KEYUP and ev.key in (pygame.K_DOWN,pygame.K_s): g.duck=False
    elif ev.type==pygame.KEYDOWN:
      k=ev.key
      if k in (pygame.K_ESCAPE,pygame.K_m): app.leave(); return
      if k==pygame.K_r: app.restart(); return
      if g.winner: continue
      if k==pygame.K_p: g.toggle_pause()
      elif k in (pygame.K_SPACE,pygame.K_UP,pygame.K_w):
        if g.paused: g.toggle_pause()
        else: g.jump()
      elif k in (pygame.K_DOWN,pygame.K_s): g.duck_action()
    elif ev.type==pygame.MOUSEBUTTONDOWN and ev.button==1:
      if app.result:
        _,again,menu=result_buttons()
        if again.collidepoint(ev.pos): app.restart(); return
        if menu.collidepoint(ev.pos): app.leave(); return
        continue
      action=next((k for k,r in dino_control_rects() if r.collidepoint(ev.pos)),None)
      if action=='menu': app.leave(); return
      if action=='restart': app.restart(); return
      if action=='save' and not g.winner:
        g.paused=True; g.accum=0.; app.press('save'); return
      if action=='pause': g.toggle_pause()
      elif action=='duck': g.duck_action(True)
      elif action=='jump' or (action is None and 155<=ev.pos[1]<625):
        if g.paused: g.toggle_pause()
        else: g.jump()


# Fons independents dels taulers# Fons independents dels taulers i les fitxes. Els patrons es calculen una vegada.
ACTIVE_BACKGROUND = "menu"
FRAME_COLOR = (213,226,233)
_BROWSER_FRAME = None
_FRAME_SURFACE = None
_FRAME_TILE = None
_FRAME_TILE_KEY = None
_BACKGROUND_CACHE = {}
_BG_IMAGE_CACHE = {}

def background_selector_rects():
  return pygame.Rect(222,61,34,32), pygame.Rect(444,61,34,32)

def background_palette(target, key=None):
  key = key if key is not None else SAVE["backgrounds"].get(target,"auto")
  if key == "auto" or key not in BACKGROUND_THEMES:
    return BACKGROUND_DEFAULTS.get(target,BACKGROUND_DEFAULTS["menu"])
  item=BACKGROUND_THEMES[key]
  return (*item["palette"],item["motif"])


def load_background_photo(filename):
  if not filename:
    return None
  if filename in _BG_IMAGE_CACHE:
    return _BG_IMAGE_CACHE[filename]
  image = None
  for root in (os.path.dirname(os.path.abspath(__file__)), os.getcwd()):
    path = os.path.join(root, "assets", "backgrounds", filename)
    if os.path.exists(path):
      try:
        image = pygame.image.load(path).convert()
        break
      except pygame.error:
        pass
  _BG_IMAGE_CACHE[filename] = image
  return image

def background_surface(target, key=None, size=(WIDTH,HEIGHT)):
  key=key if key is not None else SAVE["backgrounds"].get(target,"auto")
  ck=(target,key,size)
  if ck in _BACKGROUND_CACHE: return _BACKGROUND_CACHE[ck]
  top,bottom,accent,motif=background_palette(target,key)
  w,h=size; surf=pygame.Surface(size)
  for y in range(h):
    k=y/max(1,h-1)
    pygame.draw.line(surf,tuple(round(a+(b-a)*k) for a,b in zip(top,bottom)),(0,y),(w,y))
  item = BACKGROUND_THEMES.get(key, {}) if key in BACKGROUND_THEMES else {}
  if item.get("image"):
    photo = load_background_photo(item.get("image"))
    if photo is not None:
      iw, ih = photo.get_size()
      scale = max(w / max(1, iw), h / max(1, ih))
      pw, ph = max(1, round(iw * scale)), max(1, round(ih * scale))
      photo = pygame.transform.smoothscale(photo, (pw, ph))
      surf.blit(photo, ((w - pw) // 2, (h - ph) // 2))
      tint = pygame.Surface(size, pygame.SRCALPHA)
      tint.fill((*top, 58))
      surf.blit(tint, (0, 0))
      haze = pygame.Surface(size, pygame.SRCALPHA)
      for yy in range(h):
        kk = yy / max(1, h - 1)
        col = tuple(round(a + (b - a) * kk) for a, b in zip(top, bottom))
        pygame.draw.line(haze, (*col, 28), (0, yy), (w, yy))
      surf.blit(haze, (0, 0))
      vign = pygame.Surface(size, pygame.SRCALPHA)
      pygame.draw.rect(vign, (0, 0, 0, 26), (0, 0, w, h), 0, border_radius=1)
      pygame.draw.rect(vign, (255, 255, 255, 16), (10, 10, w - 20, h - 20), 2, border_radius=16)
      surf.blit(vign, (0, 0))
  layer=pygame.Surface(size,pygame.SRCALPHA)
  c=(*accent,38)
  step=max(12,w//14)
  if motif=="ratlla":
    # Retícula inspirada en les línies dels taulers i les fitxes de Ratlla.
    # Motiu vectorial original, sense imatges externes.
    unit = min(w / 700, h / 750)
    tile = max(26, round(168 * unit))
    r = max(8, round(47 * unit))
    lw = max(1, round(1.3 * unit))
    dot = max(1, round(3.4 * unit))
    for j, y in enumerate(range(tile//2, h+tile, tile)):
      for x in range(tile//2-(j%2)*tile//2, w+tile, tile):
        # Tres quadrats concèntrics i connectors, com el joc clàssic.
        sizes = [r, max(5,round(r*.66)), max(3,round(r*.32))]
        for z in sizes:
          pygame.draw.rect(layer, (*accent,39), (x-z,y-z,2*z,2*z), lw)
        z=sizes[-1]
        for a,b in (((x-r,y),(x-z,y)),((x+z,y),(x+r,y)),((x,y-r),(x,y-z)),((x,y+z),(x,y+r))):
          pygame.draw.line(layer,(*accent,39),a,b,lw)
        for px,py in ((x-r,y-r),(x+r,y+r),(x,y-r)):
          pygame.draw.circle(layer,(*accent,60),(px,py),dot)
        pygame.draw.circle(layer,(*accent,37),(x+r,y-r),dot,lw)
    for y in range(tile//3,h,tile):
      for x in range(tile//3,w,tile):
        pygame.draw.circle(layer,(*accent,30),(x,y),max(1,lw))
    # Doble filet decoratiu, continu a totes les pantalles del menú.
    for inset in (max(3,round(8*unit)),max(6,round(13*unit))):
      if w>2*inset and h>2*inset:
        pygame.draw.rect(layer,(*accent,48),(inset,inset,w-2*inset,h-2*inset),lw,border_radius=max(2,round(15*unit)))
  elif motif=="grid":
    for x in range(-h,w,step*2):
      pygame.draw.line(layer,c,(x,0),(x+h,h),1)
      pygame.draw.line(layer,c,(x+w,0),(x+w-h,h),1)
  elif motif=="dots" or motif=="stars":
    for j,y in enumerate(range(step//2,h,step)):
      for x in range(step//2+(j%2)*step//2,w,step):
        pygame.draw.circle(layer,c,(x,y),max(1,step//12))
        if motif=="stars" and (x+y)%3==0: pygame.draw.line(layer,c,(x-3,y),(x+3,y),1)
  elif motif=="waves":
    for j,y in enumerate(range(0,h+step,step)):
      for x in range(-step+(j%2)*step//2,w,step):
        pygame.draw.arc(layer,c,(x,y,step,step),0,math.pi,1)
  elif motif=="leaves":
    for j,y in enumerate(range(step//2,h,step*2)):
      for x in range(step//2+(j%2)*step,w,step*2):
        pygame.draw.ellipse(layer,c,(x,y,max(5,step//2),max(3,step//5)),1)
        pygame.draw.line(layer,c,(x,y+step//5),(x+step//2,y),1)
  elif motif=="photo":
    for y in range(0,h,step*2):
      pygame.draw.line(layer,(*accent,18),(0,y),(w,y),1)
  else:
    for i in range(3):
      yy=int(h*(.67+i*.11)); pts=[(0,h)] + [(x, int(yy+math.sin(x/max(1,w)*7+i)*h*.065)) for x in range(0,w+max(1,w//20),max(1,w//20))] + [(w,h)]
      pygame.draw.polygon(layer,(*accent,20+i*9),pts)
  surf.blit(layer,(0,0)); _BACKGROUND_CACHE[ck]=surf
  return surf

def paint_frame(display, w, h, origin):
  """Continua el patró de la pantalla als marges de l'escriptori."""
  global _FRAME_TILE, _FRAME_TILE_KEY
  key = (id(_FRAME_SURFACE), w, h)
  if key != _FRAME_TILE_KEY:
    _FRAME_TILE = pygame.transform.smoothscale(_FRAME_SURFACE, (w,h))
    _FRAME_TILE_KEY = key
  dw,dh = display.get_size()
  for y in range(origin[1]%h-h,dh,h):
    for x in range(origin[0]%w-w,dw,w):
      display.blit(_FRAME_TILE,(x,y))


def background_png(surf):
  """Codificació PNG RGB amb la biblioteca estàndard (compatible amb pygbag)."""
  import struct
  w,h=surf.get_size()
  raw=pygame.image.tostring(surf,"RGB")
  stride=w*3
  rows=b"".join(b"\x00"+raw[y*stride:(y+1)*stride] for y in range(h))
  def chunk(tag,data):
    return struct.pack(">I",len(data))+tag+data+struct.pack(">I",zlib.crc32(tag+data)&0xffffffff)
  return (b"\x89PNG\r\n\x1a\n"+chunk(b"IHDR",struct.pack(">IIBBBBB",w,h,8,2,0,0,0))
          +chunk(b"IDAT",zlib.compress(rows,6))+chunk(b"IEND",b""))


def draw_background(target):
  global FRAME_COLOR,_BROWSER_FRAME,_FRAME_SURFACE
  surf=background_surface(target)
  SCREEN.blit(surf,(0,0))
  _FRAME_SURFACE=surf
  FRAME_COLOR=background_palette(target)[1]
  frame_key=(target,SAVE["backgrounds"].get(target,"auto"))
  if HAS_JS and frame_key != _BROWSER_FRAME:
    try:
      col='#%02x%02x%02x'%FRAME_COLOR
      try:
        encoded=base64.b64encode(background_png(surf)).decode('ascii')
        css=f'{col} url("data:image/png;base64,{encoded}") center center / contain repeat'
      except Exception:
        css=col
      js.window.eval("document.documentElement.style.setProperty('background',"+json.dumps(css)+",'important');document.body.style.setProperty('background',"+json.dumps(css)+",'important');")
      _BROWSER_FRAME=frame_key
    except Exception: pass

# ---------------------------------------------------------------
# DINO RUN — EXPEDITION: expansió del motor anterior
# ---------------------------------------------------------------
_DinoBase = DinoRun
_DINO_MODES = {'endless':('Infinit',0), 'sprint':('Sprint',60), 'expedition':('Expedició',120)}
_DINO_SKINS = [('Verd clàssic',0,(72,126,92)),('Ambre',200,(192,118,56)),('Glacial',500,(74,147,184)),('Obsidiana',1000,(90,81,117)),('Esmeralda',1800,(35,164,123)),('Daurat',3000,(205,164,62))]
_DINO_TASKS = [('temps', 'Aguanta 30 segons',30),('coins','Recull 12 monedes',12),('cleared','Esquiva 8 obstacles',8)]
DINO_HAZARDS.update(tumble=(38,38), arch=(82,36), crystal=(35,47), drone=(47,24))
DINO_LABELS.update(tumble='Planta rodolant',arch='Barrera baixa',crystal='Cristall',drone='Robot volador')
DINO_HAZARDS.update(tall_spire=(38,181),thorn_wall=(50,176))
DINO_LABELS.update(tall_spire='Punxa gegant de ferro',thorn_wall='Cactus gegant')
DINO_STAGES += (
 ('Selva',(103,173,143),(225,240,188),(81,128,99),(48,102,77),(125,158,92),(56,82,61)),
 ('Glacera',(139,183,216),(242,249,248),(129,165,190),(107,148,175),(214,230,234),(76,112,135)),
 ('Volcà',(96,66,89),(239,154,105),(116,76,87),(85,65,77),(163,97,72),(69,48,55)))

def dino_profile():
  return SAVE['dino_profile']

def dino_unlocked(index):
  return SAVE.get('dino_best',0)>=_DINO_SKINS[index][1]

class DinoRun(_DinoBase):
  def __init__(self):
    super().__init__(); self.version=4; self.mode_id='endless'; self.skin=0
    self.double=0; self.combo=0; self.max_combo=0
    self.bonus=0; self.tasks=[]; self.particles=[]; self.floaters=[]; self.complete=False; self.combo_timer=0
    self.mode_id=dino_profile().get('mode','endless')

  def tall_obstacle_size(self, kind):
    """Fa els obstacles gegants una mica més petits a mesura que avances metres."""
    base_w, base_h = DINO_HAZARDS[kind]
    metres = self.distance / 18.0
    scale = max(0.78, 1.0 - metres * 0.00035)
    w = max(28, round(base_w * scale))
    h = max(120, round(base_h * scale))
    return w, h
    if self.mode_id not in _DINO_MODES: self.mode_id='endless'
    self.skin=dino_profile().get('skin',0)
    if not isinstance(self.skin,int) or not 0<=self.skin<len(_DINO_SKINS) or not dino_unlocked(self.skin): self.skin=0

  def migrate(self):
    version=self.version
    if version==4:
      # Base v3 understands the same collision schema; preserve additional state.
      self.version=3
    super().migrate(); self.version=4
    if version!=4:
      self.mode_id='endless'; self.bonus=0; self.tasks=[]; self.complete=False
    self.particles=[]; self.floaters=[]; self.score=self.move_count//6+self.coins*20+self.bonus
    self.__dict__.pop('slow',None)
    self.pickups=[p for p in self.pickups if p.get('kind')!='slow']
    if version!=4: self.platforms=[]
    self.platforms=getattr(self,'platforms',[])
    self.upper_entries=getattr(self,'upper_entries',0)
    self.upper_frames=getattr(self,'upper_frames',0)
    self.high_cleared=getattr(self,'high_cleared',0)
    if 'lenta' in self.notice.lower(): self.notice=''; self.notice_timer=0
    # Retira les trampes del pont també en reprendre una partida antiga.
    self.hazards=[h for h in self.hazards if h.get('lane')!='upper' and h.get('type') not in ('upper_spike','upper_totem')]
    # Actualitza obstacles de partides antigues per poder jugar només saltant.
    for h in self.hazards:
      if h['type']=='bird': h['y']=self.ground-37
      elif h['type']=='highbird': h['y']=self.ground-150
      elif h['type']=='arch': h['y']=self.ground-h['h']
      elif h['type']=='drone': h['y']=self.ground-40

  def jump(self):
    before=self.jumps
    super().jump()
    if before==1 and self.jumps==2:
      self.emit(DINO_X+27,self.y-4,(239,226,175),10)

  def reward(self):
    return super().reward()+len(self.tasks)*3+(10 if self.complete else 0)

  def emit(self,x,y,color,count=10):
    for i in range(count):
      a=i*2.39996; v=1.5+i%4*.65
      self.particles.append({'x':float(x),'y':float(y),'vx':math.cos(a)*v,'vy':math.sin(a)*v-1.2,'life':22+i%9,'color':color})
    self.particles=self.particles[-100:]

  def pop(self,text,x,y,col):
    self.floaters.append({'text':text,'x':x,'y':y,'life':48,'color':col}); self.floaters=self.floaters[-12:]

  def spawn(self):
    # Cada cinc onades hi ha una ruta alternativa elevada. El carril
    # inferior continua disponible: no cal pujar per completar una cursa.
    if self.seconds>=8 and (self.waves+1)%5==0:
      self.waves+=1; self.last_kind='platform'
      x=float(WIDTH+12); y=self.ground-172; speed=self.speed
      long_bridge=self.seconds>=24 and random.random()<.55
      width=1700 if long_bridge else 900
      self.platforms.append({'x':x,'y':y,'w':width,'speed':speed,'long':long_bridge})
      # Carril inferior: obstacles espaiats perquè segueixi sent una ruta segura.
      lower_pattern=['cactus'] if not long_bridge else ['cactus','rock']
      lower_offsets=[220] if not long_bridge else [220, 1000]
      for kind,off in zip(lower_pattern,lower_offsets):
        w,h=DINO_HAZARDS[kind]
        self.hazards.append({'type':kind,'x':x+off,'y':float(self.ground-h),'w':w,'h':h,'vx':-speed,'warn':0,'lane':'lower'})
      # Carril superior lliure: totes les monedes es poden recollir corrent.
      coin_count=16 if long_bridge else 10
      for i in range(coin_count):
        off=85+i*(width-170)/(coin_count-1)
        self.pickups.append({'kind':'coin','x':x+off,'y':float(y-29)})
      self.notice='Pont segur · doble salt per pujar'; self.notice_timer=155 if long_bridge else 145
      return
    if self.seconds>=12 and (self.waves+1)%4==0:
      self.waves+=1; kind=random.choice(('tall_spire','thorn_wall')); self.last_kind=kind
      w,h=self.tall_obstacle_size(kind); x=float(WIDTH+12)
      self.hazards.append({'type':kind,'x':x,'y':float(self.ground-h),'w':w,'h':h,'vx':-self.speed,'warn':0})
      self.notice='Obstacle alt · doble salt!'; self.notice_timer=150
      coin_y=float(self.ground-h-44)
      for i in range(3): self.pickups.append({'kind':'coin','x':x-35+i*34,'y':coin_y})
      return
    if self.seconds<10 or random.random()<.62:
      super().spawn()
    else:
      choices=['tumble','crystal']+(['arch','drone'] if self.seconds>=20 else [])
      kind=random.choice([k for k in choices if k!=self.last_kind] or choices)
      self.last_kind=kind; self.waves+=1
      w,h=DINO_HAZARDS[kind]; y=self.ground-h
      if kind=='arch': y=self.ground-h
      if kind=='drone': y=self.ground-40
      self.hazards.append({'type':kind,'x':float(WIDTH+12),'y':float(y),'w':w,'h':h,'vx':-self.speed,'warn':0})
      for i in range(3): self.pickups.append({'kind':'coin','x':float(WIDTH-12+i*32),'y':float(self.ground-112)})
    # Bonus objects never overlap a forced jump/duck window.
    if self.waves%6==0:
      self.pickups.append({'kind':'double','x':float(WIDTH+180),'y':float(self.ground-30)})

  def step(self):
    prev_coins=self.coins; prev_cleared=self.cleared; had_shield=self.shield
    prev_upper=self.upper_entries; prev_high=self.high_cleared
    self.combo_timer=max(0,self.combo_timer-1)
    if not self.combo_timer: self.combo=0
    # New pickups handled separately (base treats every other item as magnet).
    extras=[p for p in self.pickups if p['kind']=='double']
    self.pickups=[p for p in self.pickups if p['kind'] not in ('slow','double')]
    self.double=max(0,self.double-1)
    double_active=bool(self.double)
    super().step()
    for p in extras:
      p['x']-=self.speed
      if not self.winner and self.player_rect().inflate(14,14).colliderect(pygame.Rect(round(p['x'])-11,round(p['y'])-11,22,22)):
        self.double=480; self.notice='Monedes x2 · 8 s'
        self.notice_timer=100; self.emit(p['x'],p['y'],(130,220,241)); continue
      if p['x']>-30: self.pickups.append(p)
    if self.coins>prev_coins:
      delta=self.coins-prev_coins; self.combo+=delta; self.combo_timer=420; self.max_combo=max(self.max_combo,self.combo)
      gain=delta*20 if double_active else 0; self.bonus+=gain
      if self.combo//5>(self.combo-delta)//5: self.bonus+=50; self.pop('COMBO +50',DINO_X+50,self.y-75,(255,221,101))
      self.emit(DINO_X+35,self.y-35,(255,203,65),9)
    if had_shield and not self.shield:
      self.combo=0; self.emit(DINO_X+30,self.y-35,(108,223,240),20)
    if self.cleared>prev_cleared: self.emit(DINO_X+70,self.ground-5,(224,192,135),5)
    if self.upper_entries>prev_upper:
      self.bonus+=50; self.pop('+50',DINO_X+35,self.y-72,(255,221,101))
    if self.high_cleared>prev_high:
      self.bonus+=50; self.pop('+50',DINO_X+35,self.y-72,(255,221,101))
    for p in self.particles:
      p['x']+=p['vx']; p['y']+=p['vy']; p['vy']+=.10; p['life']-=1
    self.particles=[p for p in self.particles if p['life']>0]
    for p in self.floaters: p['y']-=.65; p['life']-=1
    self.floaters=[p for p in self.floaters if p['life']>0]
    if not self.winner:
      for key,label,target in _DINO_TASKS:
        value=self.seconds if key=='temps' else getattr(self,key)
        if key not in self.tasks and value>=target:
          self.tasks.append(key); self.bonus+=100; self.notice='Repte completat! +100'; self.notice_timer=110
          self.emit(DINO_X+30,self.y-40,(255,224,130),18)
      limit=_DINO_MODES[self.mode_id][1]
      if limit and self.seconds>=limit:
        self.complete=True; self.winner=True; self.hit='Objectiu completat'; self.bonus+=250
    self.score=self.move_count//6+self.coins*20+self.bonus

# Paletes del dinosaure: es canvia el color del sprite sense perdre les vores.
_DINO_COLORED={}
_old_dino_sprite=dino_sprite

def dino_skin_sprite(pose,phase,skin):
  key=(pose,phase,skin)
  if key not in _DINO_COLORED:
    s=_old_dino_sprite(pose,phase).copy()
    if skin:
      color=_DINO_SKINS[skin][2]
      for y in range(s.get_height()):
        for x in range(s.get_width()):
          c=s.get_at((x,y)); rgb=tuple(c[:3])
          if rgb in ((72,126,92),(123,168,104),(48,86,69)):
            f=1 if rgb==(72,126,92) else 1.32 if rgb==(123,168,104) else .68
            s.set_at((x,y),tuple(min(255,int(a*f)) for a in color)+(c.a,))
    _DINO_COLORED[key]=s
  return _DINO_COLORED[key]

