def dino_center_alert(title,subtitle,timer):
  pulse=(math.sin(pygame.time.get_ticks()*.012)+1)*.5
  box=pygame.Rect(170,214,360,106)
  panel=pygame.Surface((box.w,box.h),pygame.SRCALPHA)
